  `zoning` varchar(255) DEFAULT NULL,
  `parking_spaces` int(11) DEFAULT NULL,
  `ceiling_height` varchar(255) DEFAULT NULL,
  `ownership` varchar(255) DEFAULT NULL,
  `sale_condition` varchar(255) DEFAULT NULL,
  `lot_size_acres` decimal(10,2) DEFAULT NULL,
  `net_rentable_sqft` decimal(15,2) DEFAULT NULL,
  `cap_rate` decimal(5,2) DEFAULT NULL,
  `occupancy_date` date DEFAULT NULL,
  `pro_forma_noi` decimal(15,2) DEFAULT NULL,
  `price_per_unit` decimal(15,2) DEFAULT NULL,
  `price_per_acre` varchar(255) DEFAULT NULL,
  `investment_type` varchar(255) DEFAULT NULL,
  `investment_sub_type` varchar(255) DEFAULT NULL,
  `class` varchar(255) DEFAULT NULL,
  `lease_type` varchar(255) DEFAULT NULL,
  `tenancy` varchar(255) DEFAULT NULL,
  `lease_expiration` date DEFAULT NULL,
  `ground_lease` tinyint(1) DEFAULT NULL,
  `investment_highlights` longtext DEFAULT NULL,
  `summary_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`summary_details`)),
  `subtypes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`subtypes`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

