INSERT INTO `properties` (`id`, `external_id`, `name`, `description`, `marketing_description`, `asking_price`, `status`, `types`, `subtypes`, `url_slug`, `external_url`, `thumbnail_url`, `number_of_images`, `has_flyer`, `has_video`, `has_virtual_tour`, `is_in_opportunity_zone`, `activated_on`, `external_updated_on`, `created_at`, `updated_at`) VALUES
(1, 2228471, '3203 Fayetteville Rd, Raeford NC', 'Highway Commercial Opportunity in Raeford NC', '<p>Prime Highway Commercial Opportunity – 3203 Fayetteville Rd, Hoke County</p><p>Positioned along Highway 401, the rapidly growing Fayetteville Road corridor, this 3-acre commercial tract offers exceptional visibility and accessibility with 17,500 vehicles per day passing directly in front of the site.​ The property features a flat topography, making it highly development-friendly, and is already equipped with water on site and septic in place.​</p><p>The parcel is zoned Highway Commercial (HC), providing versatile potential for a wide range of retail, service, and commercial uses.​ Adding further value, a double-wide trailer will convey with the sale, offering immediate use potential or transitional space while planning for future development.​</p><p>Located in the heart of Hoke County’s expanding commercial district, this site presents a rare chance to secure a prime piece of property in a corridor experiencing rapid growth and strong demand.​</p>', 295000.00, 'On-Market', '[\"Land\"]', '[]', 'north-carolina-3203-fayetteville-rd-raeford-nc', 'https://www.crexi.com/properties/2228471/north-carolina-3203-fayetteville-rd-raeford-nc', 'https://images.crexi.com/assets/2228471/aac27c9a42af4801bb031cc1bcf72a94_716x444.jpg', 11, 1, 0, 0, 0, '2025-10-23 17:59:35', '2025-10-23 18:00:04', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(2, 2013242, '1642 Old Dixie Highway', 'Business for Sale | 11,163 SqFt', 'Turnkey established business of vintage, modern decor and furnishings, with custom hand-crafted items.​ Located in 4,600+ sq.​ ft.​, there are consignors who pay booth spaces.​ Has a garage in back, well ventilated, could be for craftsman / artist.​ Extra storage space.​ Shop runs itself.​ Approximately 50k in inventory.​ Fantastic location and great lease terms.​', 79000.00, 'On-Market', '[\"Business for Sale\"]', '[]', 'florida-1642-old-dixie-highway', 'https://www.crexi.com/properties/2013242/florida-1642-old-dixie-highway', 'https://images.crexi.com/assets/2013242/61a0553208c9413280fde05fd0364b93_716x444.jpg', 45, 1, 0, 0, 0, '2025-07-13 11:02:32', '2025-08-20 12:02:01', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(3, 848657, 'Old Fredericksburg Rd Suite D102', 'Office | 2,251 SqFt', '<p><strong><span style=\"color: rgba(0, 0, 0, 1)\">Newly Remodeled Dental Office in Prime Southwest Austin Location!</span></strong></p><p><span style=\"color: rgba(0, 0, 0, 1)\">Suite D102 at 5901 Old Fredericksburg Road offers 2,251 SF of beautifully finished dental space within a quiet, professional office condominium project in highly desirable Southwest Austin.​ Conveniently located just minutes from US 290/71, Loop 1 (MoPac), and the Y at Oak Hill, this location provides easy access to major corridors while serving the rapidly growing South and West Austin communities.​</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">This thoughtfully designed suite features a spacious waiting room and nurse’s station, five dental operatories (plumbed with sinks), two restrooms, a break room, large lab, and two built-in workstations.​ With two private entrances, ample parking, and professional stone-and-metal exterior construction, this space is ideal for a dental professional looking to establish or expand their practice in a highly visible and accessible location.​</span></p>', 999000.00, 'On-Market', '[\"Office\"]', '[]', 'texas-old-fredericksburg-rd-suite-d102', 'https://www.crexi.com/properties/848657/texas-old-fredericksburg-rd-suite-d102', 'https://images.crexi.com/assets/848657/f4abccde69644a5c945643a9c6d7cab5_716x444.jpg', 9, 1, 0, 0, 0, '2025-04-02 18:48:22', '2025-08-25 18:33:08', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(4, 1841059, '313 W Chicago St', '313 W Chicago St', '<p><span style=\"color: rgba(60, 60, 60, 1)\"><span>MOXIE Real Estate + Development is pleased to exclusively offer Colony House Apartments For Sale.​ This 33-unit complex consists of three buildings.​ With an attractive unit mix, there is 1 studio, 26 2-bed units, 4 3-bed units and 1 4-bed unit.​ The property has had many substantial capital improvements completed.​ Please contact us today to request the T12, rent roll and OM.​</span></span></p>', 2805000.00, 'On-Market', '[\"Multifamily\"]', '[]', '313-w-chicago-st', 'https://www.crexi.com/properties/1841059/313-w-chicago-st', 'https://images.crexi.com/assets/1841059/7853a1e4743d4fd398f4bffc71447069_716x444.jpg', 32, 1, 0, 0, 0, '2025-11-11 18:58:47', '2025-11-11 19:13:12', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(5, 1757260, '231-235 N 2nd St - Old City Parkominium', '12,835 SF Specialty Building Offered at $4,300,000 in Philadelphia, PA 19106', '<p><span style=\"color: rgba(0, 0, 0, 1)\">Opportunity to acquire a significant share with majority control of deeded parking spaces within a condo parking garage in Old City, Philadelphia.​ With ownership of approximately 195 out of the total 281 spaces, a majority owner could have the authority to manage the garage\'s operations, establishing an income stream of both monthly and transient/daily customers and, if preferred, hiring a third-party management company.​ This kind of ownership could be highly valuable, especially in a historic neighborhood with limited parking availability.​</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">Bulk Price for 192 spaces = $</span><a href=\"4.3M\" target=\"_blank\"><span style=\"color: rgba(0, 0, 0, 1)\">4.3M</span></a></p>', 4300000.00, 'On-Market', '[\"Special Purpose\"]', '[]', 'pennsylvania-231-235-n-2nd-st---old-city-parkominium', 'https://www.crexi.com/properties/1757260/pennsylvania-231-235-n-2nd-st---old-city-parkominium', 'https://images.crexi.com/assets/1757260/c0cebbcab6884cf880dfc7936cddb360_716x444.jpg', 11, 0, 0, 0, 0, '2025-01-28 17:52:50', '2025-08-18 17:31:23', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(6, 1767205, '3505 N El Paso St', 'Functional Single Tenant Industrial located 10 mins N of downtown C.Springs', '<p>Address: 3505 N El Paso St</p><p>Available SF: <u>+</u> 4,700 - 10,040 RSF</p><p>Total Building SF: <u>+</u> 10,040 RSF</p><p>Zoning: LI (Light Industrial)</p><p>Site Size: <u>+</u> 27,186 SF (.62 AC)</p><p>Clear Height: <u>+</u> 12’</p><p>Parking: 8 Surface Spaces</p><p>Loading: Drive In: One (1) 10’W x 10’H | Docks: Two (2) Ext</p><p>Year Built: 1962/2023</p><p>Construction: Reinforced Concrete Block</p><p></p>', 1750000.00, 'On-Market', '[\"Industrial\"]', '[]', 'colorado-3505-n-el-paso-st', 'https://www.crexi.com/properties/1767205/colorado-3505-n-el-paso-st', 'https://images.crexi.com/assets/1767205/24ff33b5fd054d6988d9c853221abf89_716x444.jpg', 10, 1, 0, 0, 0, '2025-02-04 17:23:59', '2025-09-09 20:42:35', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(7, 2194552, '3307 N Clark Street', 'Business for Sale', 'This is a turnkey opportunity to acquire fully operational and profitable French cafe with everything included.​  Cafe Paris brings timeless Parisian charm where every detail is designed for indulgence.​  Authentic French food: Croissants, Baguettes, Macarons, Sandwiches, Quiche Lorraine or Croque-Monsieur + varieties of coffees.​  The recipes originated in Paris and they bring the same authentic taste to Chicago.​  Established reputation for quality and service.​  1,355 square feet of restaurant space, approximately 900 square feet of outdoor space in the rear of the restaurant, and partial use of the basement space.​  Perfect for an owner-operator or an experienced restaurateur looking to expand their portfolio', 269000.00, 'On-Market', '[\"Retail\",\"Business for Sale\"]', '[]', 'illinois-3307-n-clark-street', 'https://www.crexi.com/properties/2194552/illinois-3307-n-clark-street', 'https://images.crexi.com/assets/2194552/a55c4024b1ca41709a211ac068404fe3_716x444.jpg', 11, 1, 0, 0, 0, '2025-09-29 09:41:18', '2025-10-07 09:44:58', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(8, 2159142, '2801 W Washington Street', 'Industrial | 7,675 SqFt', '<p>Prime Industrial/Self-Storage Investment Opportunity – Midland, TX! This well-maintained 7,675 SF storage facility features 38 fully leased units, offering immediate and reliable cash flow.​ Built in 2004 and zoned commercial, the property is strategically positioned for long-term growth and stability in a high-demand market.​ With a 100% occupancy rate, this asset delivers strong, consistent income and presents a turnkey opportunity for investors seeking a stable addition to their portfolio.​</p><p>Situated at 2801 W Washington Street, this property benefits from a strategic location in Southwest Midland, offering strong value for industrial or self-storage investors.​ With near-immediate access to Front Street, it connects easily to major transportation routes, enhancing logistical convenience for tenants or operations.​ Positioned on a 0.44-acre lot, the site provides both functionality and room for future flexibility in an active industrial area in MIdland.​</p>', 575000.00, 'On-Market', '[\"Industrial\"]', '[]', 'texas-2801-w-washington-street', 'https://www.crexi.com/properties/2159142/texas-2801-w-washington-street', 'https://images.crexi.com/assets/2159142/1b745e70a002498d8f3db75ba0bd985e_716x444.jpg', 6, 1, 0, 0, 0, '2025-08-27 22:10:44', '2025-09-02 22:39:42', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(9, 1733505, 'Bank-Owned | Investment / Owner-User Opportunity', 'Excellent visibility along South Broadway', '<p><span style=\"color: rgba(124, 124, 124, 1)\"><span>Blue West Capital is pleased to exclusively offer for sale a vacant property located in Centennial, CO.​ This 2,200-square-foot property is positioned along South Broadway just north of East Arapahoe Road.​</span></span></p><p><span style=\"color: rgba(124, 124, 124, 1)\"><span>This investment provides the buyer with an opportunity to operate out of the existing building or lease it as an investment property.​ It is a highly trafficked corridor allowing for great visibility along South Broadway.​ The site also features 8 off-street parking spaces and a monument sign.​</span></span></p><p><span style=\"color: rgba(124, 124, 124, 1)\"><span>The property is located in a dense and affluent trade area with 93,932 residents and an average annual household income of $121,789 within three miles.​</span></span></p>', 430000.00, 'On-Market', '[\"Office\",\"Retail\",\"Mixed Use\"]', '[]', 'colorado-bank-owned-investment-owner-user-opportunity', 'https://www.crexi.com/properties/1733505/colorado-bank-owned-investment-owner-user-opportunity', 'https://images.crexi.com/assets/1733505/d136e01f0d0444d4b84d430f099acba1_716x444.jpg', 4, 1, 0, 0, 0, '2025-05-12 14:30:15', '2025-09-15 15:26:27', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(10, 2243872, 'Storefront Retail - Victorville, CA', 'Bank Foreclosure Sale', '<p>Avison Young is pleased to present the opportunity to</p><p>acquire a vacant, retail storefront in Victorville, California.​</p><p>This retail building has 3 vacant spaces that can be</p><p>utilized for various uses.​ There is an additional 4th space</p><p>on C Street that can used as a 4th retail space or can be</p><p>turned into an apartment unit.​ This ±4,725 SF building</p><p>sits on a ±0.24 AC lot.​ This building has ample parking</p><p>and is only 1 mile from the 15 Freeway.​</p><p>This space is a great fit for buyer looking to serve the</p><p>Victorville area, or owner-users seeking a vacant retail</p><p>storefront close to major highways.​</p><p>This is a lender foreclosure whereby the lender/seller</p><p>took back the real estate via foreclosure.​ Lender/seller</p><p>has very limited information and buyer will be acquiring</p><p>in “as-is” condition.​</p>', 360000.00, 'On-Market', '[\"Retail\",\"Mixed Use\"]', '[]', 'california-storefront-retail---victorville-ca', 'https://www.crexi.com/properties/2243872/california-storefront-retail---victorville-ca', 'https://images.crexi.com/assets/2243872/2dc718abe4194c7e9f744cce3a169ba7_716x444.jpg', 1, 0, 0, 0, 1, '2025-11-06 16:56:00', '2025-11-10 16:59:59', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(11, 1890589, 'HARTWELL CABINS & RVS', '20-Units, Built-in 2022', NULL, 1800000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'georgia-hartwell-cabins-rvs', 'https://www.crexi.com/properties/1890589/georgia-hartwell-cabins-rvs', 'https://images.crexi.com/assets/1890589/475adba3742a4c2db9fe757091a0ca2e_716x444.jpg', 4, 0, 0, 0, 0, '2025-04-09 21:38:51', '2025-11-05 19:06:18', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(12, 1169557, 'VACANT Gas Station - QUALIFIES FOR BONUS DEPRECIATION', 'HIGH TRAFFIC COUNTS - BONUS DEPRECIATION!', '<p>Prime Net Lease is pleased to present the exclusive opportunity to purchase a Vacant BP Gas Station located at 231 NJ Route 206 in Bordentown, New Jersey (the “Property”).​ The Property has been operating as a successful gas station for over 50 years! The current tenant has just been evicted and the Seller wants to sell the property.​</p><p>Qualifies for 100% Bonus Depreciation.​</p><p>Property is situated at the convergence of US Route 206 and US Route 130, two of the area’s primary commercial and commuter roadways.​ These two heavily trafficked roadways directly connect to Interstate 295 (1-mile away) and Interstate 95 (1.5-miles away).​ The Property lies less than 1-mile from downtown Borden town and is surrounded by densely populated residential neighborhoods and enjoys convenient access to area schools and retailers.​ The Property enjoys good visibility, signage, and frontage along US Routes 130 & 206.​ Bordentown is an affluent bedroom community of Philadelphia, located 30-miles northeast of the city.​</p><p>An investor can acquire this site and lease it out to a fuel operator.​</p>', 795000.00, 'On-Market', '[\"Retail\"]', '[]', 'new-jersey-bp-gas-station', 'https://www.crexi.com/properties/1169557/new-jersey-bp-gas-station', 'https://images.crexi.com/assets/1169557/f148fcd6cb9148ef8240fb85f1a43210_716x444.jpg', 5, 0, 1, 0, 0, '2025-11-13 19:52:24', '2025-11-13 19:52:24', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(13, 2170073, 'Pendleton Place Townhome Portfolio - New Construction', 'Multifamily Investment Opportunity | 4 Units- New Construction', '<p>4 new-construction townhomes in Pendleton, SC, minutes to Clemson University and Tri-County Technical College, delivering immediate lease-up potential in a high-demand rental corridor.​ Each 3BR/2.5BA unit is ±1,320 SF, never occupied, separately metered for electric and water, and includes two parking spaces.​</p><p>Offered as a portfolio at $699,000 ($174,750 per door).​ Addresses: 120, 122, 124 & 126 Pendleton Place Way (GPS: 804 S Mechanic St).​ Other details: HOA $175/mo.​ Clean, modern finishes and turnkey condition make this an easy add to any buy-and-hold strategy near a major university market.​</p>', 699000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'south-carolina-pendleton-place-townhome-portfolio---new-construction', 'https://www.crexi.com/properties/2170073/south-carolina-pendleton-place-townhome-portfolio---new-construction', 'https://images.crexi.com/assets/2170073/e8507330d3e54a02bd735240803b8c89_716x444.jpg', 26, 0, 0, 0, 0, '2025-09-11 16:08:31', '2025-10-21 16:01:05', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(14, 2257475, '2926-2932 Eliot Cir', '8 unit value add in north Denver metro!', 'Prime small-multifamily opportunity in Westminster, CO—two side-by-side 4-plexes, 8 units total, each building approximately 3,518 SF.​ Because these are two separate 4-unit buildings, buyers may be able to take advantage of Fannie Mae financing, creating more flexibility in loan structure, down payment, and long-term hold strategy compared to larger commercial multifamily.​\r\n\r\nBuilt in 1962 and situated in an R-4 zoned area, the property is currently 50% occupied, giving investors a blend of immediate income and clear value-add upside through lease-up and repositioning.​ Located in a strong Westminster rental corridor, this is an excellent fit for investors looking to scale their portfolio with finance-friendly, small-balance multifamily in a high-demand market.​', 1400000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'colorado-eliot-properties', 'https://www.crexi.com/properties/2257475/colorado-eliot-properties', 'https://images.crexi.com/assets/2257475/596eea9e2617403c9f113a24739a4165_716x444.jpg', 31, 0, 0, 0, 0, '2025-11-06 19:34:56', '2025-11-25 17:00:02', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(15, 2253390, 'Phoenix Building | Duluth, MN', 'Retail | 7.42% CAP | 14,112 SqFt', '<p><strong>Fully Occupied Building -</strong> <br>This mixed-use retail/office building is fully occupied with a great mix of tenants.​ Starbucks anchors the building, which also has an attached parking ramp that generates income for the property.​ </p><p><strong>Prime Downtown Location -</strong> <br>Great corner location in downtown Duluth.​ Centrally located with signage, high traffic counts, and is also connected by skyway in downtown.​ </p><p><strong>Recent Property Updates -</strong> <br>Multiple CAPEX projects including windows, parking lot, A/C units, elevators, sprinkler system, and the roof is serviced biannually.​</p><p><strong>Market Advantage -</strong> <br>In the Duluth CBD there are no office properties under construction, and nothing has been delivered in the downtown CBD submarket for the past ten years.​</p><p><strong>Strategic Economic Hub -</strong> <br>Duluth serves as an economic hub for a large area of northern Minnesota and Wisconsin.​ The Port of Duluth-Superior sits at the farthest inland point on the Great Lakes, which allows it to serve as a hub for shipments for the entire upper Midwest.​</p><p><strong>Vibrant Community -</strong> <br>Duluth boasts a diverse and dynamic community and has a strong educational and cultural scene.​ Duluth\'s population is known for its strong ties to the region\'s natural beauty, with many residents enjoying outdoor activities in the city\'s scenic surroundings.​</p>', 1775000.00, 'On-Market', '[\"Retail\"]', '[]', 'minnesota-phoenix-building-duluth-mn', 'https://www.crexi.com/properties/2253390/minnesota-phoenix-building-duluth-mn', 'https://images.crexi.com/assets/2253390/c7f8268194de43338282cfd5d4ce145b_716x444.jpg', 5, 0, 0, 0, 1, '2025-11-13 20:06:30', '2025-11-18 16:50:40', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(16, 2253325, '1615 Tremont St', 'Special Purpose | 2,720 SqFt', '<p>Presenting this unique 2,720+/- SF building at 1615 Tremont St, Cincinnati, OH.​ Built in 1880 on a stone foundation, comprised of a beautiful sanctuary and a community hall, zoned RMX, and ideal for special purpose / religious use.​ A prime opportunity for small churches or church branches in the heart of Cincinnati.​</p>', 139000.00, 'On-Market', '[\"Special Purpose\"]', '[]', 'ohio-1615-tremont-st', 'https://www.crexi.com/properties/2253325/ohio-1615-tremont-st', 'https://images.crexi.com/assets/2253325/c2462436c2f341cd909e6626b416d004_716x444.jpg', 10, 1, 0, 0, 1, '2025-11-13 16:13:05', '2025-11-13 19:35:03', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(17, 2170275, 'Turn-Key Office Space | 460 E King Street', 'Office | 6,520 SqFt', '<ul><li>​<p>3 floors of office space available with the ability to demise by floor</p></li><li>​<p>Total SF: 6,520 SF</p></li><li>​<p>Private parking lot with 23 spaces</p></li><li>​<p>Visible pylon signage</p></li><li>​<p>Traffic count: 6,000 ADT</p></li><li>​<p>Steps from the SEPTA Malvern Station</p></li><li>​<p>Close proximity to Route 202, Lancaster Ave & the PA Turnpike</p></li><li>​<p>Approximately 25 miles west of Philadelphia</p></li><li>​<p>Permitted Uses: Educational, Office or religious</p></li><li>​<p>Conditional Uses: Daycare</p></li></ul>', 1200000.00, 'On-Market', '[\"Office\"]', '[]', 'pennsylvania-turn-key-office-space-460-e-king-street', 'https://www.crexi.com/properties/2170275/pennsylvania-turn-key-office-space-460-e-king-street', 'https://images.crexi.com/assets/2170275/1e75ed35a05940e5a22db2428fea5464_716x444.jpg', 9, 1, 0, 0, 0, '2025-09-11 18:27:07', '2025-11-04 14:41:30', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(18, 1924651, '11949 Hogans Alley', 'River\'s Bend Community', '<p><span style=\"font-size: 13px\">One South Commercial is pleased to </span>bring to market 11949 Hogans Alley, a former golf course maintenance facility with a conditional use permitfor RV and Boat Storage.​ </p><p><span style=\"font-size: 13px\">The property sits adjacent to Chesterfield county’s latest park project located along the James River.​ The </span>property includes a 7500 SF steel building and is ready for development into a profitable storage business.​ Currently access exists through the River’s Bend neighborhood but will soon be moved to a private drive from a new county road being constructed into the park.​ Once complete the public will be able to access the facility.​</p><p>Market comparables show indoor storage bays renting for roughly $395/ month per spot and outdoor spaces renting for $100/ month.​ Don’t miss this opportunity to develop a high demand business for the River Bend community and greater Chester region! </p><p><br></p><div><br></div>', 475000.00, 'On-Market', '[\"Self Storage\",\"Multifamily\",\"Land\",\"Special Purpose\"]', '[]', 'virginia-zoned-rvboat-storage-facility', 'https://www.crexi.com/properties/1924651/virginia-zoned-rvboat-storage-facility', 'https://images.crexi.com/assets/1924651/98076424479b4bedb79d744d194583cb_716x444.jpg', 8, 1, 0, 0, 0, '2025-05-09 16:08:31', '2025-10-20 15:47:12', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(19, 1767281, '1716 Raccoon', 'Retail | 8,700 SqFt', '<p>Multi-tenant retail plaza with positive cash flow </p><p>Adjacent to Huntington Bank </p><p>Access from Raccoon Rd and New Rd </p><p>Great for owner / occupant (2,800 SF available) - put your business here and collect rent from tenants </p><p>Great opportunity for professional office or retail user </p><p></p>', 399000.00, 'On-Market', '[\"Retail\"]', '[]', 'ohio-1716-raccoon', 'https://www.crexi.com/properties/1767281/ohio-1716-raccoon', 'https://images.crexi.com/assets/1767281/81ef8b3cd2fe4999af71cfef45b939d0_716x444.jpg', 11, 1, 0, 0, 0, '2025-02-04 18:23:57', '2025-10-22 14:51:57', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(20, 2169116, '53390 E US Highway 60', 'Mobile Home Park', '<p>This 3.61-acre offering features a 15-unit mobile home park ideally located between Miami and Superior in the desirable “Top of the World” area, where temperatures average 15 degrees cooler than the Valley—supporting strong, year-round occupancy and tenant demand.​ In addition to the mobile home units, the property includes four buildings: a duplex, a single-unit apartment building, and two commercial structures.​ The current owner pays for water (via a private well), sewer (septic), property taxes, insurance, and maintenance.​ Rent increases are already underway, providing immediate income growth with additional upside potential for investors.​</p>', 750000.00, 'On-Market', '[\"Mobile Home Park\"]', '[]', 'arizona-53390-e-us-highway-60', 'https://www.crexi.com/properties/2169116/arizona-53390-e-us-highway-60', 'https://images.crexi.com/assets/2169116/3a223254a1b74f5692acfc905df7c24e_716x444.jpg', 11, 1, 0, 0, 0, '2025-09-15 23:51:49', '2025-10-01 17:13:56', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(21, 2243597, '2160 FORBES Street', 'Historic Turnkey Riverside Quadraplex fully leased!', 'Built in 1918, this classic Riverside four-unit property showcases period craftsmanship and thoughtful updates throughout.​ Each residence features spacious living and dining areas with original hardwood floors, wide moldings, and abundant natural light from large, wood-framed windows.​ Updated kitchens blend vintage character with modern convenience, offering ample cabinetry, solid-surface counters, and contemporary appliances.​ Bathrooms include a mix of preserved tile details and newer fixtures.​ Screened front porches extend the living space outdoors, creating a welcoming transition from the tree-lined street.​ Private entries, separate utilities, and dedicated parking add comfort and functionality.​ Carefully maintained by a long-time restoration professional, the interiors balance historic charm with the efficiency and livability expected today.​ Each spacious unit offers:  Original Harwood Floors & Architectural details unique to Historic Riverside Homes.​  \nPrivate Screened Porches \nDedicated covered parking for each unit \nFenced rear patio and yard for entertaining\nSeparately metered utilities for tenant independence\n\nRecent Capital Improvements deliver peace of mind: \nRoof replaced in 2022\nElectrical Upgrades in 2022\nSome HVAC replacements in 2022\nPlumbing cleanout all routed to basement for easy access\nAudio Visual System wired with HUB in attic\nAttic area has the possibility of being renovated to a Penthouse unit\nFront and rear stairs\nStorm Shutters and Panels', 1250000.00, 'On-Market', '[\"Multifamily\",\"Land\"]', '[]', 'florida-2160-forbes-street', 'https://www.crexi.com/properties/2243597/florida-2160-forbes-street', 'https://images.crexi.com/assets/2243597/5d0cf2857ac84753bbd6e99270c15800_716x444.jpg', 39, 1, 0, 0, 0, '2025-11-03 13:06:46', '2025-11-18 18:20:51', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(22, 1233731, '320 West Main Street', 'Owner occupied iconic restaurant located in former railroad terminal and office building', 'For sale', 539000.00, 'On-Market', '[\"Retail\"]', '[]', 'new-york-320-west-main-street', 'https://www.crexi.com/properties/1233731/new-york-320-west-main-street', 'https://images.crexi.com/assets/1233731/818960e27e8f4d098bb71f7d0fc2aae4_716x444.jpg', 5, 1, 0, 0, 0, '2023-09-21 12:48:40', '2025-07-18 15:27:54', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(23, 2145338, 'Bank on Bank Street Absolute NNN', 'Office | 7.00% CAP | 4,100 SqFt', '<p>The Building has been renovated on the 1st floor to meet the historic atmoshphere and the Bank Street Enviroment.​ It is an Absolute NNN.​</p><p>The rich history of the building shows that it was a bank with an old bank vault still in tact but not functional still in the building.​ Another additional part of the building is an unfinished 850 sf single apartment with antique wood paneling and tounge and groove wood floors from the original construction.​ The original design in all downtowns was for the building owner to live in the upstairs apartment.​</p><p><span style=\"color: rgba(0, 0, 0, 1)\">Today Downtown Decatur is in the process of over 300 million in various projects.​ These projects include an 80 room  Calhoun College Dorm, 80 room Hotel, and a parking garage on the block between 1st Avenue and 2nd Avenue.​ Calhoun and Athens State University has a brand new Fine Arts division building on 2ndAvenue Downtown that is connected to the new dorms and new dance studio.​</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">The Cooks Natural History Museum has been in operation downtown withing the last 5 years plus they have just been approved to build a 120 room hotel and a 4 level parking garage.​ </span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">Also 205 Class A Apartments on Bank Street called Bank Street Station has been approved.​ Green Point Ag is building their headquarters downtown too with over 200 employees.​ </span></p><p>CSX has promised to build a cargo port from its trains to truck and barge loading terminal.​</p><p>There is a new commercial zone setting up on the river for new restaurants and retail within walking distance.​</p><p><span style=\"color: rgba(0, 0, 0, 1)\">The city has also been rebuilding the entrance from Hwy 31/6th Ave with its beautification project and is currently underway.​ </span></p><p>The City of Decatur has over $300 million in current and resently approved projects for the downtown area.​</p><p><span style=\"color: rgba(0, 0, 0, 1)\"><br></span></p>', 850000.00, 'On-Market', '[\"Office\"]', '[]', 'alabama-bank-on-bank-street', 'https://www.crexi.com/properties/2145338/alabama-bank-on-bank-street', 'https://images.crexi.com/assets/2145338/aa699a93957d4e19ab94eeeadda6f85e_716x444.jpg', 33, 1, 0, 0, 0, '2025-08-20 15:30:20', '2025-10-14 03:49:59', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(24, 1826362, '2001 W St Road', 'Industrial', 'NEWLY COMPLETED & ALREADY OVER 50% OCCUPIED!! VICTORY LANE AUTO VAULTS OF FORT LAUDERDALE is an exclusive GATED enclave of Automotive Condominiums catering to CAR COLLECTORS & AUTOMOTIVE CONNOISSEURS! Conveniently located in East Ft Lauderdale at I-95 and State Rd 84 (Marina Mile Blvd ) adjacent to Ft Lauderdale-Hollywood International Airport.​ This PRIVATE & SECURE 1000 SF WAREHOUSE (20\' X 50\') has FULL A/C SYSTEM, electric hurricane approved 12\' ROLL UP DOOR, 22 FT ceiling height.​ FULLY CUSTOMIZABLE W/ SELLER WILLING TO PERFORM ALL ASPECTS OF UPGRADES FROM MEZZANINE 2ND LEVELS, CAR LIFTS, BATHROOMS, PAINTING, TILE, LIGHTING, ETC! Don\'t miss your chance to be part of this exciting new concept made up of like-minded automotive aficionados! INQUIRE ABOUT OTHER SIZES AVAILABLE! SEE VIDEO.​', 625000.00, 'On-Market', '[\"Industrial\"]', '[]', 'florida-2001-w-st-road', 'https://www.crexi.com/properties/1826362/florida-2001-w-st-road', 'https://images.crexi.com/assets/1826362/961dd608a4e145c782aa8634e2b0f91e_716x444.jpg', 35, 1, 0, 0, 0, '2025-03-11 12:01:40', '2025-08-22 12:01:25', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(25, 1826036, '4112-4112 Junius St, Dallas, TX | 100% Occupied 4-Plex', '100% Occupied 4-Plex | 7.30% CAP', '<p>This 4,284 square-foot, fully leased four-plex presents an excellent investment opportunity with an estimated 7.30% cap rate, based on month-to-month leases with normalized rents.​ The property has been extensively renovated, including updates to the electrical system (four meters), plumbing (one water meter), roof, foundation, and central HVAC.​ Interior improvements feature new cabinetry, millwork, flooring, and windows.​ Additionally, the property includes a tiny home at the rear, which can serve as an office, and a three-car garage for tenants.​</p><p>Strategically located just off Interstate 30, the property is situated in a densely residential area near Baylor Scott & White Hospital and various retail establishments.​ The landlord conducts monthly inspections to ensure proper maintenance of each unit.​ For more information, please contact Ross Miller.​</p>', 949000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'texas-4112-4112-junius-st-dallas-tx-100-occupied-4-plex', 'https://www.crexi.com/properties/1826036/texas-4112-4112-junius-st-dallas-tx-100-occupied-4-plex', 'https://images.crexi.com/assets/1826036/266f3ce9836d48c8b519688c39774d47_716x444.jpg', 16, 0, 0, 0, 0, '2025-03-10 22:45:24', '2025-10-29 21:50:18', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(26, 1914627, 'Candlewood Suites San Antonio Med Ctr Development Project', 'STRATEGICALLY LOCATED EXTENDED-STAY HOTEL DEVELOPMENT OPPORTUNITY', '<p><strong>For more information, please visit the HVS marketing website to electronically execute the confidentiality agreement and get access to the Virtual Deal Room (VDR): </strong><a href=\"https://brokerage.hvs.com/listing/?id=152672\"><strong>LINK HERE</strong></a></p><p><span style=\"color: rgba(85, 85, 85, 1)\">HVS Brokerage & Advisory, as the exclusive representative of ownership, is pleased to present the opportunity to acquire a strategically located 2.36-acre parcel totaling 102,845 square feet, fully entitled for the development of an 86-key Candlewood Suites hotel and an adjacent pad site in San Antonio, Texas.​ The property is located approximately three miles northwest of the South Texas Medical Center (STMC), a major hub for medical research and healthcare in the region.​</span></p><h2 style=\"text-align: center\"><strong><span style=\"color: rgba(177, 28, 17, 1)\">PRICE REDUCTION: $1,375,000</span></strong></h2><p style=\"text-align: center\">Ownership is motivated to sell the property and has agreed to reduce the price to $1,375,000.​ Please contact Matthew Omansky for more details.​</p>', 1375000.00, 'On-Market', '[\"Hospitality\",\"Land\"]', '[]', 'texas-candlewood-suites-san-antonio-med-ctr-development-project', 'https://www.crexi.com/properties/1914627/texas-candlewood-suites-san-antonio-med-ctr-development-project', 'https://images.crexi.com/assets/1914627/3c0c31ddeeb14b3d9d00ac02f729997d_716x444.jpg', 13, 1, 0, 1, 0, '2025-04-28 16:56:02', '2025-10-13 13:49:56', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(27, 2170532, '$1 Auction - REIT Sale | Former Advance Auto Parts | 16K VPD', 'ABSOLUTE $1 AUCTION | Former Advance Auto Parts | 16K VPD | 2021 Built | AUCTION NOVEMBER 3-5', '<p>Register to Bid and Access Due Diligence Documents on RealINSIGHT Marketplace</p><p><span style=\"color: rgba(74, 74, 74, 1)\">Marcus & Millichap and RI Marketplace are pleased to present a vacant, free-standing retail building located at 2329 W North Avenue in Milwaukee, Wisconsin (the “Property”).​ Formerly occupied by Advance Auto Parts, the Property is being offered significantly below replacement cost, providing an excellent opportunity for owner/users or investors to acquire a highly visible and strategically positioned asset at a significant discount.​ FIRST BID MEETS RESERVE!<br><br>Built in 2021, the Property consists of a one-story, free-standing retail building containing ±7,054 square feet, with 27 total surface parking spaces on a ±0.833-acre parcel.​ The site is positioned on a hard corner and is easily accessible via two (2) ingress/egress curb cuts and 145’ frontage along West North Avenue and 249’ frontage along North 23rd Street.​ Zoned CS, Commercial Service District, this zoning offers favorable flexible zoning allowing for a variety of uses.​<br><br>The Property is located in Milwaukee, approximately 2-miles north of downtown.​ Once known primarily for its breweries and as the home of Harley-Davidson, the metro is diversifying from its manufacturing roots as the health care, business services and technology sectors expand.​ The transformation is especially evident in downtown Milwaukee, where major projects — including high-rise apartments, Northwestern Mutual’s headquarters and the BMO Tower — have changed the skyline.​ The Property benefits from being located on a hard-corner with frontage along both W North Avenue (±16,492 VPD) and North 23rd Street within a dense and established commercial area.​ North Avenue serves as a major east-west arterial roadway with nearby access to I-43 (±165K VPD) providing excellent regional connectivity throughout Milwaukee and its suburbs.​ The Property is situated approximately ±2.5-miles from Downtown Milwaukee, home to major corporate campuses such as Northwestern Mutual’s headquarters and the BMO Tower.​ Retail activity is further supported by strong nearby national and local retailers including Popeyes, Save a Lot, Checkers, Auto Zone, Walgreens, Family Dollar, and more.​ Additional educational demand generators include the Marquette University (±1.9-mi) with over 11,000 enrolled students and University of Wisconsin-Milwaukee (±4-mi) serving approximately 22,937 (2023) students.​ The Property is positioned within an extremely dense trade area, serving ±239,604 residents within a 3-mi radius and 484,853 residents with an average household income exceeding $71k within a 5-mile radius.​</span></p>', 125000.00, 'On-Market', '[\"Retail\"]', '[]', 'wisconsin-1-auction---reit-sale-former-advance-auto-parts-16k-vpd', 'https://www.crexi.com/properties/2170532/wisconsin-1-auction---reit-sale-former-advance-auto-parts-16k-vpd', 'https://images.crexi.com/assets/2170532/f58620e8f7da409d930830da8a8daba4_716x444.jpg', 10, 0, 0, 0, 1, '2025-09-11 22:11:17', '2025-09-30 18:54:34', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(28, 1841792, '2209 S Ocean Blvd', 'Hospitality', 'Welcome to the newly transformed Indigo Hotel, an oceanfront sanctuary located at 2209 S.​ Ocean Blvd, Myrtle Beach, SC.​\nCompletely redesigned in 2025, our hotel seamlessly blends modern aesthetics with luxurious elegance to offer guests an\nunparalleled coastal experience.​ Our 54 oceanfront rooms are thoughtfully designed to cater to diverse preferences: One-Bedroom\nSuites: Ideal for guests seeking additional space and privacy, these suites feature separate living areas and fully equipped\nkitchens.​ Large Efficiency Units: Combining comfort and convenience, these units come with kitchen facilities, perfect for extended\nstays or family vacations.​ Amenities: Direct Beach Access: Step directly from the hotel onto the pristine sands of Myrtle Beach,\nperfect for sunbathing, swimming, or leisurely strolls along the shore.​ Outdoor Pool and Hot Tub: Relax in our heated outdoor pool\nor unwind in the hot tub, both offering serene ocean vistas.​ Complimentary Wi-Fi: Stay connected with high-speed internet access\navailable throughout the property.​ Nearby Attractions: Indigo Hotel\'s prime location offers easy access to a variety of attractions,\nshopping, and dining options: Myrtle Beach Boardwalk & Promenade: A lively 1.2-mile stretch featuring shops, restaurants, and\nentertainment venues, just a short drive away.​ SkyWheel Myrtle Beach: Experience panoramic coastal views from this nearly 200\n-foot-tall observation wheel, located at the promenade.​ The Market Common: An upscale district offering a blend of shopping,\ndining, and entertainment options.​ Myrtle Beach State Park: Explore maritime forests, walking trails, and unspoiled beaches in this\nnatural haven.​ Brookgreen Gardens: Located in nearby Murrells Inlet, this expansive garden boasts impressive sculptures and\ndiverse flora.​ The 2nd Ave Pier : A classic fishing pier offering live entertainment, restaurants, a café, and stunning ocean views.​\nRipley’s Believe It or Not!: Explore oddities and curiosities at this popular museum, situated within the primary tourist hub 2 miles\nfrom the hotel.​ Indigo Hotel\'s prime location offers proximity to a variety of attractions, shopping, and dining options.​ The Grand\nStrand Experience Myrtle Beach, part of South Carolina\'s famed Grand Strand, offers over 60 miles of sandy shores and a\nplethora of activities: Golf: With numerous world-class golf courses, the area is a golfer\'s paradise.​ Water Sports: Engage in jet\nskiing, parasailing, and paddle boarding along the coast.​ Shopping: From outlet malls to boutique shops, there\'s something for\nevery shopper.​ Dining: Savor fresh seafood and regional specialties at a variety of local restaurants.​ Myrtle Beach continues to\nthrive as a top tourist destination: Visitor Statistics: In 2023, the area welcomed 17.6 million visitors, who contributed over twelve\nbillion in spending, marking a 4.7% increase from the previous year.​ Festivals and Events: The region hosts multiple festivals and\nshows annually, attracting diverse audiences and enhancing the cultural landscape.​ Population Growth: Horry County has been\namong the fastest-growing counties in the nation in recent years, reflecting the area\'s appeal to both tourists and new residents.​ ', 7900000.00, 'On-Market', '[\"Hospitality\"]', '[]', 'south-carolina-2209-s-ocean-blvd', 'https://www.crexi.com/properties/1841792/south-carolina-2209-s-ocean-blvd', 'https://images.crexi.com/assets/1841792/8fc91ae6775b4dafb034071ebf029b73_716x444.jpg', 37, 1, 0, 0, 0, '2025-03-25 14:21:07', '2025-10-17 13:51:11', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(29, 2228314, 'Newbury Village Townhomes & Apartments', 'Multifamily | 81 Units | $65,432/unit', '<p>MMG Real Estate Advisors is pleased to present the opportunity to acquire Newbury Village, an 81-unit multifamily community located in Burlington, Iowa.​ Built in 1978 and renovated in 2006, the property offers a highly attractive mix of predominantly townhome-style units with private entrances and full-size in-unit laundry.​ Newbury Village benefits from a strong amenity package, stable renter demographics, and a proven path for rental upside through light cosmetic upgrades.​</p>', 5300000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'iowa-newbury-village', 'https://www.crexi.com/properties/2228314/iowa-newbury-village', 'https://images.crexi.com/assets/2228314/dab8e2fe2d4c4444980d76f1e605f8f7_716x444.jpg', 24, 0, 0, 0, 1, '2025-10-23 15:36:37', '2025-11-25 16:11:36', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(30, 647889, 'Manhattan Off Market Non Union Hotels - Multiple Location', 'Hospitality | 1,000 Keys | $550,000/key', '<p><br>A few off market non union hotels for sale.​</p><p>Manhattan Prime Prime Location</p><p>100,000 sq.​ ft.​ to 900,000 sq, ft.​</p><p>3 stars to 5 stars hotels<br></p><p><br></p><p>Hotel Real Estate Group<br>Simon Lou<br>President / CEO<br>445 Park Av 9th Floor<br>New York NY 10022<br>M: +1 917 328 3611<br>E: hotel107@aol.​com<br><br><br></p>', 550000000.00, 'On-Market', '[\"Hospitality\"]', '[]', 'new-york-manhattan-off-market-unionized-hotels-multiple-location', 'https://www.crexi.com/properties/647889/new-york-manhattan-off-market-unionized-hotels-multiple-location', 'https://images.crexi.com/assets/647889/a9719b8b261f4b38b77cce2de112869d_716x444.jpg', 3, 1, 0, 0, 0, '2021-07-30 16:40:42', '2025-10-05 16:27:38', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(31, 1841480, '350 N Kimball', 'Industrial | 30,000 SqFt', '<p>You can do all three in this beautiful, distinctive brick warehouse/loft space.​ The J.​ S.​</p><p>Brown Mercantile Co.​ building was built in 1917 as a Warehouse for the distribution of</p><p>goods.​ Unique architectural features include: a vintage freight elevator, massive wood</p><p>support posts and beams, exposed brick walls & original steel walkway plating.​</p><p>Renovations include; approx.​ 5,000 sq.​ ft.​ of finished living space, all new windows,</p><p>refinished maple entry door, heated concrete auto ramp at first floor garage with a</p><p>new automatic roll up door, and security system.​</p>', 745000.00, 'On-Market', '[\"Industrial\"]', '[]', 'wyoming-350-n-kimball', 'https://www.crexi.com/properties/1841480/wyoming-350-n-kimball', 'https://images.crexi.com/assets/1841480/ea8be0122cfc47b58f23470528fe94f1_716x444.jpg', 20, 1, 0, 0, 1, '2025-03-24 20:40:35', '2025-11-19 17:23:47', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(32, 2228152, '107 MEADOWLARK LN MOBILE HOME PARK', 'Land', '<p>4 acres</p><p>currently a mobile home park that needs TLC</p><p>3 mobile home leased $450 per month</p><p>1 lot rental for $250 per month</p><p></p>', 349000.00, 'On-Market', '[\"Mobile Home Park\",\"Land\"]', '[]', 'pennsylvania-107-meadowlark-ln-mobile-home-park', 'https://www.crexi.com/properties/2228152/pennsylvania-107-meadowlark-ln-mobile-home-park', 'https://images.crexi.com/assets/2228152/b7ff0248eaf945d9bd982f50da55d348_716x444.jpg', 1, 1, 0, 0, 0, '2025-10-23 13:43:08', '2025-11-05 17:45:04', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(33, 1816840, '7-Eleven | Sacramento, CA', 'Strong Infill Location | 396,000 Residents within 5 Miles', '<p>Long-Term Commitment: 11 years remaining on the lease with three 5-year renewal options, ensuring stability (*asset qualifies for bonus depreciation).​</p><p>7-Eleven Corporate Lease: Leased to 7-Eleven, Inc.​, one of the world’s leading convenience store operators</p><p>Rental Growth: 10% rent escalations every five years, providing a predictable increase in NOI.​</p><p>Assumable Debt: Attractive assumable debt with a 3.51% interest rate.​</p><p>Minimal Landlord Responsibility: Net lease, with the tenant responsible for all taxes, insurance, and most maintenance.​</p><p>Prime Location: Situated on Stockton Blvd, across from a Walmart-anchored shopping center, ensuring constant customer traffic.​</p><p>High Visibility & Traffic: Located at a major intersection with traffic counts exceeding 33,600 vehicles per day on Florin Rd.​</p><p>Proximity to Downtown: Just 6.5 miles from downtown Sacramento, a major economic and business hub.​</p><p>ÂPopulation Density: Over 396,000 residents within a 5-mile radius, with strong projected growth</p>', 6774000.00, 'On-Market', '[\"Retail\"]', '[]', 'california-7-eleven-sacramento-ca', 'https://www.crexi.com/properties/1816840/california-7-eleven-sacramento-ca', 'https://images.crexi.com/assets/1816840/77bd168be781407bbbc7091cf970aadc_716x444.jpg', 6, 0, 0, 0, 1, '2025-10-11 05:55:15', '2025-10-11 06:00:11', '2025-12-16 11:07:51', '2025-12-16 11:07:51'),
(34, 1914946, 'Wild Boar Apartments', '100% Occupied, All 3 Bedroom Units, Near WashU in University City, St. Louis, MO', '<p>CBRE is pleased to offer for sale 7723-7741 Wild Plum Avenue (Wild Boar Apartments), a 24-unit apartment community located in University City, a suburb of St.​ Louis,</p><p>Missouri.​ This property benefits from its proximity to Washington University (16,552 students), a major educational institution, as well as the vibrant Delmar Loop, a renowned entertainment and retail district in University City.​ The area’s unique blend of suburban charm and urban convenience makes it an attractive option for students, faculty, and professionals alike.​ With its strategic location just nine miles from Lambert-St.​ Louis International Airport and six miles from downtown St.​ Louis, this property offers easy access to the city’s cultural and recreational attractions, making it an ideal investment opportunity in the St.​ Louis MSA.​</p><p>Built in 1957 and renovated in 2008, the Property offers an investor the rare opportunity to acquire a stabilized asset with proven operating performance and tremendous upside potential.​ 100% of the units are in classic or near classic condition, allowing new ownership the opportunity to push rents through further continued unit upgrades or increasing in-place rents to market rate.​ The Property features a mix of 2 and 3 bedroom apartment homes with 1.5 baths.​ Unit amenities include air conditioning, hardwood floors, ceiling fans, washer/dryer hookups, kitchen appliances, and reserved parking.​</p><p>With a convenient centralized location, Wild Boar Apartments is situated in University City which borders Ladue and Clayton, which are some of the wealthiest municipalities in the St.​ Louis MSA (St.​ Louis Business Journal) and fall within the top 100 wealthiest suburbs in the United States (Bloomberg-2019).​</p>', 3200000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'missouri-wild-boar-apartments', 'https://www.crexi.com/properties/1914946/missouri-wild-boar-apartments', 'https://images.crexi.com/assets/1914946/1355f4490e014750a112344c4199d14e_716x444.jpg', 18, 0, 0, 0, 0, '2025-04-28 21:09:27', '2025-10-24 14:25:35', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(35, 1581210, 'Courtshire', 'Income producing property. Only 10 minutes from Downtown Houston', '<p><strong><span style=\"color: rgba(0, 0, 0, 1)\"><span>Boasting four fully-occupied units, this property promises a steady stream of income from day one.​ Whether you\'re a seasoned investor or exploring your first income property, seize the chance to secure a profitable asset in one of Houston\'s most coveted locations.​ Don\'t miss out on this exceptional opportunity to elevate your investment portfolio.​ Contact us today to schedule a viewing.​</span></span></strong></p>', 460000.00, 'On-Market', '[\"Multifamily\"]', '[]', 'texas-courtshire', 'https://www.crexi.com/properties/1581210/texas-courtshire', 'https://images.crexi.com/assets/1581210/b544f61a4d17497ca9dfa57e9af1ea79_716x444.jpg', 2, 1, 0, 0, 0, '2024-07-06 04:07:36', '2025-10-02 18:28:55', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(36, 1816819, '521 E 14th Street', 'Retail | 3,168 SF', NULL, 741000.00, 'On-Market', '[\"Retail\"]', '[]', 'iowa-521-e-14th-street', 'https://www.crexi.com/properties/1816819/iowa-521-e-14th-street', 'https://images.crexi.com/assets/1816819/5183b23d206848f5811195712572b284_716x444.jpg', 12, 1, 0, 0, 0, '2025-02-27 16:55:35', '2025-09-03 13:38:13', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(37, 2174792, 'Downtown Frisco Development Opportunity', 'Developemt Oppurtunity in Downtown Frisco', '<h4><strong>Prime Development Opportunity in the Heart of Frisco</strong></h4><p>Located within walking distance of Frisco’s vibrant Main Street attractions, this versatile property is ideal for <strong>commercial development</strong>.​ The site is <strong>pre-demolished</strong>, offering a clean slate for construction, and includes key infrastructure such as a <strong>grease trap</strong>, making it especially appealing for food-service ventures.​</p><p>Additional highlights:</p><ul><li>​<p><strong>Core-tested</strong> and ready for development</p></li><li>​<p><strong>Sidewalk inspection passed</strong> — all city compliance up to date</p></li><li>​<p>Excellent pedestrian access and street visibility</p></li></ul><p>Don’t miss this rare opportunity to invest in a rapidly growing and highly walkable area of Frisco.​</p><p></p>', 652000.00, 'On-Market', '[\"Mixed Use\",\"Multifamily\",\"Land\",\"Special Purpose\"]', '[]', 'texas-downtown-frisco-development-oppurtunity', 'https://www.crexi.com/properties/2174792/texas-downtown-frisco-development-oppurtunity', 'https://images.crexi.com/assets/2174792/9c071a480dd04f279b55ec8eba1acb7d_716x444.jpg', 6, 0, 1, 0, 0, '2025-09-15 18:48:57', '2025-10-01 17:30:11', '2025-12-16 11:07:52', '2025-12-16 11:07:52');
