INSERT INTO `property_details` (`id`, `property_id`, `zoning`, `parking_spaces`, `ceiling_height`, `ownership`, `sale_condition`, `lot_size_acres`, `net_rentable_sqft`, `cap_rate`, `occupancy_date`, `pro_forma_noi`, `price_per_unit`, `price_per_acre`, `investment_type`, `investment_sub_type`, `class`, `lease_type`, `tenancy`, `lease_expiration`, `ground_lease`, `investment_highlights`, `summary_details`, `subtypes`, `created_at`, `updated_at`) VALUES
(85, 85, 'Single Family', NULL, NULL, NULL, NULL, 1.54, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<h4><strong><span style=\"color: rgba(0, 0, 0, 1)\">Experience Main Floor Living in Grand Style.</span></strong></h4><p><span style=\"color: rgba(0, 0, 0, 1)\">This Silverthorne gem embodies fine finishes and the Western lifestyle in grand fashion. The main floor living design ensures that all essential spaces are easily accessible, providing a seamless and luxurious living experience.</span></p><h4><strong><span style=\"color: rgba(0, 0, 0, 1)\">Why Silverthorne?</span></strong></h4><p><a href=\"https://www.denverpost.com/2022/09/09/silverthorne-hikes-bikes-hotels-beers-travel-guide/\"><u><span style=\"color: rgba(17, 85, 204, 1)\">Silverthorne is more than just a place to live; it’s a lifestyle.</span></u></a><span style=\"color: rgba(0, 0, 0, 1)\"> With easy access to </span><a href=\"https://www.colorado.com/colorado-ski-resorts\"><u><span style=\"color: rgba(17, 85, 204, 1)\">world-class ski resorts</span></u></a><span style=\"color: rgba(0, 0, 0, 1)\">, pristine hiking trails, and the Raven Golf Course, residents can enjoy year-round outdoor activities. The town itself offers a vibrant cultural scene, excellent dining options, and a close-knit community that makes everyone feel at home.</span></p><h4><strong><span style=\"color: rgba(0, 0, 0, 1)\">Perfect for Luxury Living and Investment</span></strong></h4><p><span style=\"color: rgba(0, 0, 0, 1)\">This home is not only an exceptional place to live but also an </span><a href=\"https://www.silverthorne.org/business-resources/economic-development\"><u><span style=\"color: rgba(17, 85, 204, 1)\">outstanding investment opportunity</span></u></a><span style=\"color: rgba(0, 0, 0, 1)\">. Whether you are looking to retire in style, find a family retreat, or invest in a luxury property, this estate offers everything you could desire.</span></p>', '{\"Asking Price\":\"$8,390,000\",\"Property Type\":\"Hospitality, Special Purpose\",\"Sub Type\":\"Golf Course\",\"Investment Type\":\"Owner\\/User\",\"Investment Sub Type\":\"luxury\",\"Square Footage\":\"12,888\",\"Net Rentable (SqFt)\":\"9,342\",\"Units\":\"1\",\"Beds\":\"16\",\"Year Built\":\"2009\",\"Stories\":\"2\",\"Zoning\":\"Single Family\",\"Lot Size (acres)\":\"1.54\",\"Sale Condition\":\"For sale by owner\"}', '[\"Golf Course\"]', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(86, 86, 'R-3', NULL, NULL, NULL, NULL, 6.57, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ul><li>​<p>A 78-unit, “B” class multifamily property located in the fast growing sub-market of Leesburg, FL</p></li><li>​<p>Attractive Loan Assumption: Freddie Mac loan with 5.5 years remaining at a 5.4% rate, full term IO, 30 year amortization at roughly 70% LTV at our list price</p></li><li>​<p>Above Market Returns: With a loan assumption, over a 9.89% cash-on-cash return for buyer day-1 which includes the tax-reassessment in the calculation</p></li><li>​<p>Incredibly well maintained and operated property with over $1.2 million of capital improvements spent since 2021 and operating at 97% economic occupancy on Seller’s T-12</p></li><li>​<p>All roofs replaced in 2021</p></li><li>​<p>Attractive unit mix of 75% two-bedroom units which include garden style and townhomes, with average square footage of nearly 1,000 square feet</p></li><li>​<p>Lack of Direct Competition: With almost no competition of comparable B class, market rate properties in the submarket, tenant demand and rent growth has stayed consistently strong at the property</p></li><li>​<p>Competitive Amenity Set: With washer/dryer connections in select two-bedroom units, on-site laundry facilities, leasing office/business center, and picnic area, Gardens on Griffin has an amenity package on par with newer communities</p></li><li>​<p>Family-Centric Location: Situated 15 minutes from Brownwood Paddock Square Mall, and less than 10 minutes from UF Health Leesburg Hospital, Leesburg Elementary, Middle and High School, multiple parks, museums and other entertainment venues</p></li><li>​<p>In the Path of Progress: Just minutes from one of the world’s largest retirement communities, The Villages continues to expand outward and with it brings new developments, employment, entertainment and opportunities</p></li></ul>', '{\"Asking Price\":\"$13,000,000\",\"Property Type\":\"Multifamily\",\"Sub Type\":\"Apartment Building\",\"Square Footage\":\"71,560\",\"Price per SqFt\":\"$181.67\",\"Cap Rate\":\"6.75%\",\"Pro-Forma Cap Rate\":\"8.00%\",\"Occupancy\":\"97%\",\"NOI\":\"$877,899\",\"Pro-Forma NOI\":\"$1,075,103\",\"Units\":\"78\",\"Year Built\":\"1984\",\"Buildings\":\"16\",\"Stories\":\"2\",\"Zoning\":\"R-3\",\"Lot Size (acres)\":\"6.57\",\"APN\":\"15-19-24-0004-000-04500, 15-19-24-0004-000-07300\",\"Price\\/Unit\":\"$166,666.67 \"}', '[\"Apartment Building\"]', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(87, 87, 'Residential / Commercial', NULL, NULL, NULL, NULL, 34.10, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>— Attractive Returns: Double-digit cash-on-cash and high-teens IRR projected by Year 5</p><p>— Expansion Opportunity: ~17.5 acres with room for new MH/RV sites or Boat/RV storage </p><p>— Strong In-Place Cash Flow: 100+/- site, age-restricted community with nearly 100% occupancy</p><p>— Organic Rent Growth: Legacy rents offer natural upside with no major CapEx needed</p><p>— Supply-Constrained Market: Northern CA faces low MH/RV supply and rising affordability needs</p><p>— Low Turnover Tenant Base: 55+ tenants provide long-term occupancy and strong payment history</p>', '{\"Asking Price\":\"$4,400,000\",\"Property Type\":\"Mobile Home Park\",\"Sub Type\":\"Mobile Home, RV, Storage\",\"Investment Type\":\"Stabilized\",\"Investment Sub Type\":\"Expansion\",\"Class\":\"B\",\"Cap Rate\":\"7.00%\",\"Pro-Forma Cap Rate\":\"7.00%\",\"Occupancy\":\"100%\",\"Pro-Forma NOI\":\"$299,084\",\"Units\":\"100\",\"Pads\":\"100\",\"Buildings\":\"1\",\"Stories\":\"1\",\"Zoning\":\"Residential \\/ Commercial\",\"Lot Size (acres)\":\"34.1\",\"Broker Co-Op\":\"No\",\"Price\\/Pad\":\"$47,311 \",\"Ownership\":\"Partnership\"}', '[]', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(88, 88, 'TN-TBA', NULL, NULL, NULL, NULL, 0.29, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"Property Type\":\"Retail\",\"Sub Type\":\"Auto Shop\",\"Square Footage\":\"4,158\",\"Year Built\":\"1999\",\"Year Renovated\":\"2018\",\"Zoning\":\"TN-TBA\",\"Lot Size (acres)\":\"0.286\"}', '[\"Auto Shop\"]', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(89, 89, 'CBC', NULL, NULL, NULL, NULL, 0.13, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgba(33, 37, 41, 1)\"><span>As the White Mill building comes to completion in Downtown Danville and Caesar\'s Casino continues to hold its presence in the town, the opportunity to invest in infrastructure from a commercial perspective dwindles and the cost increases. This opportunity to own a commercial building in the downtown region of Danville comes at a time when many businesses are looking to be in the area of the city where there has been a lot of transformation. This building was formally a barbershop & janitorial office. There are 2 addresses and 2 entrances. This could be 2 businesses or one business could use the whole building if needed. Being walking distance from the White Mill building makes it very convenient to any business that may accommodate any residents in that complex.</span></span></p>', '{\"Asking Price\":\"$149,900\",\"Property Type\":\"Retail\",\"Sub Type\":\"Convenience Store, Grocery Store, Storefront\",\"Tenancy\":\"Vacant\",\"Square Footage\":\"2,640\",\"Price per SqFt\":\"$56.78\",\"Units\":\"1\",\"Year Built\":\"1910\",\"Year Renovated\":\"0\",\"Buildings\":\"1\",\"Zoning\":\"CBC\",\"Lot Size (acres)\":\"0.13\",\"Pumps\":\"0\",\"Broker Co-Op\":\"Yes\",\"Ownership\":\"Owner Occupied\"}', '[\"Convenience Store\",\"Grocery Store\",\"Storefront\"]', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
(90, 90, 'Residential Two-Household', NULL, NULL, NULL, NULL, 0.21, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">11,690± SF Commercial Building</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">.213± Acre</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Built in 1900</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Zoned: R-TH, Residential Two-Household</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Flexible Layout</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Updated Windows</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Stained Glass Windows</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Full Basement with Kitchen and Bar</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Within Minutes to Downtown Elyria and University Hospitals - Elyria Medical Center</span></p><p><span style=\"color: rgba(0, 0, 0, 1)\">·</span> <span style=\"color: rgba(0, 0, 0, 1)\">Close Proximity to Interstate 80 (Ohio Turnpike), US Route 20, SR 10 & SR 57</span></p><p> </p>', '{\"Asking Price\":\"$500,000\",\"Property Type\":\"Special Purpose\",\"Sub Type\":\"Religious\\/Church, School\",\"Square Footage\":\"11,690\",\"Price per SqFt\":\"$42.77\",\"Year Built\":\"1900\",\"Buildings\":\"1\",\"Stories\":\"2\",\"Zoning\":\"Residential Two-Household\",\"Lot Size (acres)\":\"0.213\",\"APN\":\"0625073103001\"}', '[\"Religious\\/Church\",\"School\"]', '2025-12-16 11:07:52', '2025-12-16 11:07:52'),
